function PageTitle({title,subtitle,action}){return <Box className="section-title-row"><Box><Typography className="section-title">{title}</Typography><Typography className="section-subtitle">{subtitle}</Typography></Box>{action}</Box>}
function Panel({title,subtitle,action,children,className=''}){return <Paper elevation={0} className={`panel ${className}`}><Box className="panel-heading"><Box><Typography className="panel-title">{title}</Typography>{subtitle&&<Typography className="panel-subtitle">{subtitle}</Typography>}</Box>{action}</Box>{children}</Paper>}
function Dashboard(){const {user,requests}=useApp();const nav=useNavigate();const isCitizen=user?.role==='Requester';const isStaff=user?.role==='Staff';const visible= isCitizen?requests:isStaff?requests.filter(r=>r.source==='mongodb'?String(r.assigneeId)===String(user.id):r.assignee===user.name):requests;const active=visible.filter(r=>r.status==='In Progress').length;const resolved=visible.filter(r=>['Resolved','Closed'].includes(r.status)).length;const critical=visible.filter(r=>r.priority==='Critical'&&r.status!=='Closed').length;const chartData=[{name:'Mon',submitted:18,resolved:12},{name:'Tue',submitted:24,resolved:16},{name:'Wed',submitted:15,resolved:18},{name:'Thu',submitted:28,resolved:20},{name:'Fri',submitted:22,resolved:17},{name:'Sat',submitted:12,resolved:9},{name:'Sun',submitted:9,resolved:8}];const distribution=[{name:'Submitted',value:requests.filter(r=>r.status==='Submitted').length,color:'#8da6b0'},{name:'In Progress',value:requests.filter(r=>r.status==='In Progress').length,color:'#e5ac53'},{name:'Resolved',value:requests.filter(r=>r.status==='Resolved').length,color:'#40947a'},{name:'Closed',value:requests.filter(r=>r.status==='Closed').length,color:'#8578a8'}];return <><Box className="welcome-row"><Box><Typography className="eyebrow">TUESDAY, 13 OCTOBER 2026</Typography><Typography className="welcome-title">{isCitizen?'Good afternoon, '+(user?.name?.split(' ')[0]||'there')+'.':'Good afternoon, '+(user?.name?.split(' ')[0]||'team')+'.'}</Typography><Typography className="welcome-subtitle">{isCitizen?'Keep track of your service requests and municipal updates.':'Here is what is happening across your municipal service operations today.'}</Typography></Box><Stack direction="row" spacing={1}><Button variant="outlined" startIcon={<CalendarMonthOutlinedIcon/>} className="date-button">Last 7 days</Button>{isCitizen&&<Button variant="contained" startIcon={<AddOutlinedIcon/>} onClick={()=>nav('/new-request')}>New request</Button>}</Stack></Box><Grid container spacing={2} className="metrics-grid"><Grid item xs={12} sm={6} lg={3}><MetricCard label={isCitizen?'My requests':'Total requests'} value={visible.length} caption={isCitizen?'All requests you have submitted':'Across all service categories'} icon={AssignmentOutlinedIcon} tone="teal" trend="+12.8%"/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label="In progress" value={active} caption="Currently being worked on" icon={HourglassEmptyOutlinedIcon} tone="amber"/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label="Resolved / closed" value={resolved} caption="Successfully completed" icon={CheckCircleOutlineOutlinedIcon} tone="blue" trend="+8.4%"/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label={isCitizen?'Need attention':'Critical priority'} value={critical} caption={isCitizen?'Requests requiring urgent attention':'Open critical requests'} icon={WarningAmberOutlinedIcon} tone="red"/></Grid></Grid><Grid container spacing={2.2} className="dashboard-charts"><Grid item xs={12} lg={8}><Panel title={isCitizen?'Request activity':'Service request activity'} subtitle="Requests submitted compared with requests resolved" action={<Chip label="This week" size="small" variant="outlined"/>}><Box className="chart-legend"><span><i className="legend-submitted"/> Submitted</span><span><i className="legend-resolved"/> Resolved</span></Box><Box className="activity-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData} barGap={5}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#edf1f2"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#839098',fontSize:12}} dy={8}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#839098',fontSize:12}}/><ChartTooltip cursor={{fill:'#f6f8f8'}}/><Bar dataKey="submitted" fill="#176b67" radius={[5,5,0,0]} maxBarSize={20}/><Bar dataKey="resolved" fill="#e4b76e" radius={[5,5,0,0]} maxBarSize={20}/></BarChart></ResponsiveContainer></Box></Panel></Grid><Grid item xs={12} lg={4}><Panel title="Request status" subtitle="Current distribution"><Box className="status-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={distribution} dataKey="value" nameKey="name" innerRadius={62} outerRadius={86} paddingAngle={4} stroke="none">{distribution.map(d=><Cell key={d.name} fill={d.color}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer><Box className="chart-center"><Typography>{visible.length}</Typography><span>Total</span></Box></Box><Box className="distribution-list">{distribution.map(d=><Box key={d.name} className="distribution-row"><span className="distribution-label"><i style={{background:d.color}}/>{d.name}</span><strong>{d.value}</strong></Box>)}</Box></Panel></Grid></Grid><Panel title={isCitizen?'Your recent requests':'Recent service requests'} subtitle={isCitizen?'Latest updates on requests you have submitted':'Latest activity across municipal departments'} action={<Button endIcon={<ArrowForwardOutlinedIcon/>} onClick={()=>nav('/requests')}>View all</Button>}><RequestTable rows={(isCitizen?visible:visible).slice(0,5)} onOpen={r=>nav(`/requests/${r.id}`)}/></Panel><Box className="bottom-insight"><Box className="insight-icon"><CheckCircleOutlineOutlinedIcon/></Box><Box><Typography className="insight-title">Service delivery at a glance</Typography><Typography className="insight-copy">Every update is recorded to help keep municipal service delivery transparent and accountable.</Typography></Box><Button onClick={()=>nav(user?.role==='Requester'?'/requests':'/reports')}>Explore activity <ArrowForwardOutlinedIcon fontSize="small"/></Button></Box></>}
function RequestsPage(){const {requests,user}=useApp();const nav=useNavigate();const [search,setSearch]=useState('');const [status,setStatus]=useState('All statuses');const [priority,setPriority]=useState('All priorities');const [category,setCategory]=useState('All categories');const list=useMemo(()=>requests.filter(r=>(user?.role!=='Requester'||true)&&(user?.role!=='Staff'||(r.source==='mongodb'?String(r.assigneeId)===String(user?.id):r.assignee===user?.name))&&(`${r.title} ${r.number} ${r.location}`.toLowerCase().includes(search.toLowerCase()))&&(status==='All statuses'||r.status===status)&&(priority==='All priorities'||r.priority===priority)&&(category==='All categories'||r.category===category)),[requests,user,search,status,priority,category]);return <><PageTitle title="Service requests" subtitle="Search, review and track municipal service requests." action={user?.role==='Requester'?<Button variant="contained" startIcon={<AddOutlinedIcon/>} onClick={()=>nav('/new-request')}>Submit request</Button>:null}/><Paper className="filter-panel" elevation={0}><TextField size="small" placeholder="Search by title, tracking number or location" value={search} onChange={e=>setSearch(e.target.value)} InputProps={{startAdornment:<SearchOutlinedIcon sx={{mr:1,color:'#829198'}}/>}} className="search-field"/><FormControl size="small" className="filter-select"><InputLabel>Status</InputLabel><Select label="Status" value={status} onChange={e=>setStatus(e.target.value)}>{['All statuses','Submitted','In Progress','Resolved','Closed'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><FormControl size="small" className="filter-select"><InputLabel>Priority</InputLabel><Select label="Priority" value={priority} onChange={e=>setPriority(e.target.value)}>{['All priorities','Low','Medium','High','Critical'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><FormControl size="small" className="filter-select"><InputLabel>Category</InputLabel><Select label="Category" value={category} onChange={e=>setCategory(e.target.value)}>{['All categories','Water & sanitation','Roads & potholes','Electricity','Waste management','Parks & public spaces'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><Button variant="outlined" startIcon={<FileDownloadOutlinedIcon/>} onClick={()=>downloadCSV(list)}>Export</Button></Paper><Panel title={`${list.length} requests found`} subtitle="Select a request to view its full details and history."><RequestTable rows={list} onOpen={r=>nav(`/requests/${r.id}`)}/></Panel></>}
function downloadCSV(rows){const csv=['Tracking number,Title,Category,Status,Priority,Location,Assigned to',...rows.map(r=>[r.number,r.title,r.category,r.status,r.priority,r.location,r.assignee].map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='civicconnect-requests.csv';a.click();URL.revokeObjectURL(url)}
function NewRequestPage(){const {setRequests,requests,categoryList,user,setAudit,refreshLiveRequests}=useApp();const nav=useNavigate();const [form,setForm]=useState({title:'',category:'Water & sanitation',priority:'Medium',description:'',location:''});const [error,setError]=useState('');const [files,setFiles]=useState([]);const [saving,setSaving]=useState(false);const [apiCategories,setApiCategories]=useState([]);useEffect(()=>{apiRequest('/categories').then(r=>setApiCategories(r.data||[])).catch(()=>{});},[]);const change=k=>e=>setForm(p=>({...p,[k]:e.target.value}));async function submit(e){e.preventDefault();if(saving)return;
 if(form.title.trim().length<5||form.description.trim().length<10||form.location.trim().length<5){setError('Please complete all fields. The title needs 5 characters, the description 10, and the address 5.');return;}
 const category=apiCategories.find(c=>c.name===form.category&&c.active!==false);
 if(!category){setError('This category is not available in MongoDB. Ask the Administrator to create an active category.');return;}
 setSaving(true);setError('');let created=null;
 try{
  const result=await apiRequest('/requests',{method:'POST',body:JSON.stringify({...form,category:category._id})});created=result.data;
  if(files.length)await uploadRequestAttachments(created._id,files);
  const r={id:created._id,number:created.number,...form,status:created.status,requester:user?.name||'',assignee:'Unassigned',createdAt:created.createdAt,updatedAt:created.updatedAt,events:[{label:'Request submitted',date:new Date(created.createdAt).toLocaleString(),done:true}],source:'mongodb'};
  try { await refreshLiveRequests(); } catch(refreshError) { console.warn('Request saved but list refresh failed:',refreshError); }setAudit(p=>[{id:Date.now(),actor:user?.name||'Citizen',action:'REQUEST_CREATED',entity:r.number,time:new Date().toLocaleString(),details:'New service request saved in MongoDB'},...p]);
  nav(`/requests/${r.id}`,{state:{created:true}});
 }catch(err){setError(created?`Request ${created.number} was saved, but attachments could not be uploaded: ${err.message}. Please contact support before submitting again.`:err.message);}
 finally{setSaving(false);}
 }return <><Button startIcon={<ArrowBackOutlinedIcon/>} onClick={()=>nav('/requests')} className="back-button">Back to requests</Button><PageTitle title="Submit a service request" subtitle="Tell your municipality what needs attention. Fields marked with an asterisk are required."/><Grid container spacing={2.5}><Grid item xs={12} lg={8}><Paper elevation={0} className="form-panel"><Box className="form-section-heading"><Box className="form-step">01</Box><Box><Typography className="panel-title">Request information</Typography><Typography className="panel-subtitle">Describe the issue clearly so the right team can help.</Typography></Box></Box>{error&&<Alert severity="error" sx={{mb:2}}>{error}</Alert>}<Box component="form" onSubmit={submit} className="request-form"><TextField required fullWidth label="Request title" placeholder="e.g. Water leak outside my home" value={form.title} onChange={change('title')} helperText="Use a short, descriptive title."/><Grid container spacing={2}><Grid item xs={12} sm={6}><FormControl fullWidth required><InputLabel>Service category</InputLabel><Select label="Service category" value={form.category} onChange={change('category')}>{(apiCategories.length?apiCategories.map(c=>({...c,id:c._id,isActive:c.active})):categoryList).filter(c=>c.isActive!==false).map(c=><MenuItem key={c.id||c._id} value={c.name}>{c.name}</MenuItem>)}</Select></FormControl></Grid><Grid item xs={12} sm={6}><FormControl fullWidth><InputLabel>Priority</InputLabel><Select label="Priority" value={form.priority} onChange={change('priority')}>{['Low','Medium','High','Critical'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl></Grid></Grid><TextField required fullWidth label="Physical address or location" placeholder="Street name, suburb, ward or nearby landmark" value={form.location} onChange={change('location')} helperText="Please provide enough detail for a municipal team to find the issue." InputProps={{startAdornment:<LocationOnOutlinedIcon sx={{mr:1,color:'#829198'}}/>}}/><TextField required fullWidth multiline minRows={5} label="Describe the issue" placeholder="What happened? When did you first notice it? Is there any immediate safety concern?" value={form.description} onChange={change('description')} inputProps={{maxLength:1000}} helperText={`${form.description.length}/1000 characters. Minimum 10 characters.`}/><Box className="upload-placeholder"><Box className="upload-symbol"><AddOutlinedIcon/></Box><Box sx={{flex:1}}><Typography className="table-primary">Supporting documents or photos</Typography><Typography className="table-secondary">Up to 3 JPEG, PNG, WebP or PDF files; 5 MB each.</Typography><Button component="label" variant="outlined" size="small" sx={{mt:1}}>Choose files<input hidden type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple onChange={e=>{const selected=Array.from(e.target.files||[]);e.target.value='';if(selected.length>3||selected.some(f=>f.size>5*1024*1024)||selected.some(f=>!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type))){setError('Select at most 3 JPEG, PNG, WebP or PDF files, each no larger than 5 MB.');return;}setError('');setFiles(selected);}}/></Button>{files.map((file,i)=><Typography key={i} variant="caption" display="block">{file.name} ({(file.size/1024/1024).toFixed(2)} MB)</Typography>)}</Box><Chip label="Optional" size="small"/></Box><Box className="form-actions"><Button variant="outlined" onClick={()=>nav('/requests')}>Cancel</Button><Button type="submit" disabled={saving} variant="contained" endIcon={<ArrowForwardOutlinedIcon/>}>{saving?'Submitting…':'Submit request'}</Button></Box></Box></Paper></Grid><Grid item xs={12} lg={4}><Paper elevation={0} className="guidance-card"><Typography className="guidance-kicker">WHAT HAPPENS NEXT</Typography><Typography className="guidance-title">Your report makes a difference.</Typography><Typography className="guidance-copy">Once you submit your request, the municipal team will review it and keep you informed as work progresses.</Typography>{[['01','Submission received','Your unique tracking number is created.'],['02','Municipal review','The right department assesses the issue.'],['03','Work in progress','A team member is assigned to resolve it.'],['04','Resolution','You can follow updates until closure.']].map(x=><Box className="guidance-step" key={x[0]}><Box className="guidance-number">{x[0]}</Box><Box><Typography className="guidance-step-title">{x[1]}</Typography><Typography className="guidance-step-copy">{x[2]}</Typography></Box></Box>)}<Box className="privacy-note"><CheckCircleOutlineOutlinedIcon/><Typography>Your contact details are used to manage this request and provide service updates.</Typography></Box></Paper></Grid></Grid></>}
function RequestDetail(){const {id}=useParams();const {requests,setRequests,user,setAudit,refreshLiveRequests}=useApp();const nav=useNavigate();const [comment,setComment]=useState('');const [snack,setSnack]=useState(false);const [snackText,setSnackText]=useState('Request updated.');const [statusBusy,setStatusBusy]=useState(false);const [statusError,setStatusError]=useState('');
const [attachments,setAttachments]=useState([]);
const [attachmentError,setAttachmentError]=useState('');
const [attachmentLoading,setAttachmentLoading]=useState(false);
const [downloading,setDownloading]=useState(null);
useEffect(()=>{
  let active=true;
  setAttachments([]);setAttachmentError('');
  const selected=requests.find(r=>String(r.id)===String(id));
  if(!selected || selected.source!=='mongodb')return ()=>{active=false};
  setAttachmentLoading(true);
  apiRequest(`/requests/${encodeURIComponent(id)}`)
    .then(result=>{if(active)setAttachments(result.data?.attachments||[])})
    .catch(err=>{if(active)setAttachmentError(err.message||'Could not load attachments.')})
    .finally(()=>{if(active)setAttachmentLoading(false)});
  return ()=>{active=false};
},[id,requests,user?.role]);
async function downloadAttachment(file){
  setDownloading(file._id);setAttachmentError('');
  try{
    const token=getAccessToken();
    const response=await fetch(`${API_BASE}/requests/${encodeURIComponent(id)}/attachments/${encodeURIComponent(file._id)}`,{
      headers:token?{Authorization:`Bearer ${token}`}:{}
    });
    if(!response.ok){
      const details=await response.json().catch(()=>({}));
      throw new Error(details.message||`Download failed (${response.status}).`);
    }
    const blob=await response.blob();
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;a.download=file.originalName||'attachment';document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch(err){setAttachmentError(err.message||'Could not download attachment.')}
  finally{setDownloading(null)}
}
const request=requests.find(r=>r.id===id);if(!request || (user?.role==='Requester' && (request.source==='mongodb'?String(request.requesterId)!==String(user?.id):request.requester!==user?.name)) || (user?.role==='Staff' && (request.source==='mongodb'?String(request.assigneeId)!==String(user?.id):request.assignee!==user?.name)))return <Paper className="panel"><Typography>Request not found or you do not have permission to view it.</Typography><Button onClick={()=>nav('/requests')}>Return to requests</Button></Paper>;const mayProcess=['Staff','Manager','Administrator'].includes(user?.role);
const statusTransitions={Submitted:['Under Review','In Progress','Rejected'],'Under Review':['In Progress','Rejected'],'In Progress':['Resolved','Under Review'],Resolved:['Closed','In Progress'],Closed:[],Rejected:[]};
async function changeStatus(nextStatus){
  if(statusBusy||nextStatus===request.status)return;
  setStatusError('');
  if(request.source!=='mongodb'){
    update({status:nextStatus,events:[...(request.events||[]),{label:`Status changed to ${nextStatus}`,date:new Date().toLocaleString(),done:true}]},'STATUS_UPDATED',`Status changed to ${nextStatus}`);
    return;
  }
  setStatusBusy(true);
  try{
    await apiRequest(`/requests/${encodeURIComponent(id)}/status`,{method:'PATCH',body:JSON.stringify({status:nextStatus})});
    await refreshLiveRequests();
    setSnackText('Request status saved to MongoDB.');setSnack(true);
  }catch(err){
    setStatusError(err.message||'Status could not be saved to MongoDB.');
  }finally{setStatusBusy(false)}
}
async function changePriority(nextPriority){
  if (request.source!=='mongodb') {setStatusError('Select MongoDB mode to save priority changes.');return;}
  setStatusBusy(true);setStatusError('');
  try {
    await apiRequest(`/requests/${encodeURIComponent(id)}/priority`,{method:'PATCH',body:JSON.stringify({priority:nextPriority})});
    await refreshLiveRequests();setSnackText('Request priority saved to MongoDB.');setSnack(true);
  }catch(err){setStatusError(err.message||'Priority could not be saved.');}
  finally{setStatusBusy(false);}
}
function update(patch,action,details){setRequests(old=>old.map(r=>r.id===id?{...r,...patch,updatedAt:new Date().toISOString()}:r));setAudit(old=>[{id:Date.now(),actor:user?.name||'User',action,entity:request.number,time:new Date().toLocaleString(),details},...old]);setSnackText('Updated in the demo.');setSnack(true)}return <><Button startIcon={<ArrowBackOutlinedIcon/>} onClick={()=>nav('/requests')} className="back-button">All requests</Button><Box className="detail-heading"><Box><Typography className="eyebrow">{request.number}</Typography><Typography className="detail-title">{request.title}</Typography><Box className="detail-chips"><StatusChip status={request.status}/><StatusChip status={request.priority}/><Chip label={request.category} size="small" variant="outlined"/></Box></Box>{mayProcess&&<Button variant="contained" startIcon={<EditOutlinedIcon/>} onClick={()=>document.getElementById('process-request')?.scrollIntoView({behavior:'smooth'})}>Update request</Button>}</Box><Grid container spacing={2.5}><Grid item xs={12} lg={8}><Panel title="Request overview" subtitle="Information provided by the requester"><Typography className="body-copy">{request.description}</Typography><Divider sx={{my:2.5}}/><Grid container spacing={2}><Grid item xs={12} sm={6}><Typography className="detail-label">LOCATION</Typography><Box className="detail-value-row"><LocationOnOutlinedIcon/><Typography>{request.location}</Typography></Box></Grid><Grid item xs={12} sm={6}><Typography className="detail-label">DATE SUBMITTED</Typography><Box className="detail-value-row"><CalendarMonthOutlinedIcon/><Typography>{new Date(request.createdAt).toLocaleString()}</Typography></Box></Grid><Grid item xs={12} sm={6}><Typography className="detail-label">REQUESTER</Typography><Typography className="detail-value">{request.requester}</Typography></Grid><Grid item xs={12} sm={6}><Typography className="detail-label">ASSIGNED STAFF</Typography><Typography className="detail-value">{request.assignee||'Unassigned'}</Typography></Grid></Grid></Panel>
<Panel title="Supporting documents and photos" subtitle="Files uploaded with this service request">
  {attachmentLoading&&<Typography className="table-secondary">Loading attachments…</Typography>}
  {attachmentError&&<Alert severity="error" sx={{mb:1}}>{attachmentError}</Alert>}
  {!attachmentLoading&&!attachmentError&&attachments.length===0&&<Typography className="table-secondary">No attachments provided.</Typography>}
  <Stack spacing={1}>
    {attachments.map(file=><Box key={file._id} sx={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:2,flexWrap:'wrap',py:1}}>
      <Box sx={{minWidth:0}}>
        <Typography className="table-primary" sx={{overflowWrap:'anywhere'}}>{file.originalName}</Typography>
        <Typography className="table-secondary">{file.mimeType||'Document'} · {typeof file.size==='number'?(file.size/1024/1024).toFixed(2)+' MB':'Size unknown'}</Typography>
      </Box>
      <Button size="small" variant="outlined" startIcon={<FileDownloadOutlinedIcon/>} disabled={downloading===file._id} onClick={()=>downloadAttachment(file)}>{downloading===file._id?'Downloading…':'Download'}</Button>
    </Box>)}
  </Stack>
</Panel><Panel title="Updates and comments" subtitle="Persisted request history and comments"><RequestCommentsPanel request={request}/></Panel></Grid><Grid item xs={12} lg={4}><Panel title="Request status" subtitle="Track progress at every stage"><Box className="status-summary"><Typography className="detail-label">CURRENT STATUS</Typography><StatusChip status={request.status}/><Typography className="detail-label" sx={{mt:2.5}}>PRIORITY LEVEL</Typography><StatusChip status={request.priority}/><Typography className="detail-label" sx={{mt:2.5}}>LAST UPDATED</Typography><Typography className="detail-value">{new Date(request.updatedAt).toLocaleString()}</Typography></Box></Panel>{mayProcess&&<Panel title="Process request" subtitle="Staff and managers only"><Box id="process-request" className="process-form"><FormControl fullWidth size="small"><InputLabel>Update status</InputLabel><Select label="Update status" value={request.status} disabled={statusBusy} onChange={e=>changeStatus(e.target.value)}>{[request.status,...(statusTransitions[request.status]||[])].map(s=><MenuItem key={s} value={s}>{s}</MenuItem>)}</Select></FormControl><FormControl fullWidth size="small"><InputLabel>Priority</InputLabel><Select label="Priority" value={request.priority} onChange={e=>changePriority(e.target.value)}>{['Low','Medium','High','Critical'].map(s=><MenuItem key={s} value={s}>{s}</MenuItem>)}</Select></FormControl>{(user?.role==='Manager'||user?.role==='Administrator')&&<StaffAssignmentControl request={request} onSaved={refreshLiveRequests}/>}{statusBusy&&<Typography className="table-secondary">Saving status to MongoDB…</Typography>}{statusError&&<Alert severity="error">{statusError}</Alert>}<Typography className="table-secondary">Status, priority, staff assignments and comments are saved to MongoDB for live requests.</Typography></Box></Panel>}</Grid></Grid><Snackbar open={snack} autoHideDuration={2500} onClose={()=>setSnack(false)}><Alert severity="success" onClose={()=>setSnack(false)}>{snackText}</Alert></Snackbar></>}
function ReportsPage(){const {requests}=useApp();const statuses=['Submitted','In Progress','Resolved','Closed'];const data=statuses.map(s=>({name:s,count:requests.filter(r=>r.status===s).length}));const cat=['Water & sanitation','Roads & potholes','Electricity','Waste management','Parks & public spaces'].map(c=>({name:c,count:requests.filter(r=>r.category===c).length}));return <><PageTitle title="Operational reports" subtitle="Monitor request volumes, resolution progress and service delivery trends." action={<Button variant="outlined" startIcon={<FileDownloadOutlinedIcon/>} onClick={()=>downloadCSV(requests)}>Export data</Button>}/><Grid container spacing={2}><Grid item xs={12} sm={6} lg={3}><MetricCard label="Total requests" value={requests.length} caption="All recorded service requests" icon={AssignmentOutlinedIcon}/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label="Resolution rate" value={`${Math.round(requests.filter(r=>['Resolved','Closed'].includes(r.status)).length/Math.max(requests.length,1)*100)}%`} caption="Resolved or closed requests" icon={CheckCircleOutlineOutlinedIcon} tone="blue"/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label="Open requests" value={requests.filter(r=>!['Resolved','Closed'].includes(r.status)).length} caption="Submitted or in progress" icon={HourglassEmptyOutlinedIcon} tone="amber"/></Grid><Grid item xs={12} sm={6} lg={3}><MetricCard label="Critical requests" value={requests.filter(r=>r.priority==='Critical'&&r.status!=='Closed').length} caption="Require priority attention" icon={WarningAmberOutlinedIcon} tone="red"/></Grid><Grid item xs={12} md={6}><Panel title="Requests by status" subtitle="Current operational workload"><Box className="report-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{left:12,right:20}}><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" axisLine={false} tickLine={false}/><YAxis type="category" dataKey="name" width={95} axisLine={false} tickLine={false} tick={{fontSize:12}}/><ChartTooltip/><Bar dataKey="count" fill="#176b67" radius={[0,5,5,0]} maxBarSize={24}/></BarChart></ResponsiveContainer></Box></Panel></Grid><Grid item xs={12} md={6}><Panel title="Requests by category" subtitle="Where service demand is concentrated"><Box className="report-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={cat} margin={{left:0,right:12,bottom:20}}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:10}} angle={-12} textAnchor="end" interval={0}/><YAxis allowDecimals={false} axisLine={false} tickLine={false}/><ChartTooltip/><Bar dataKey="count" fill="#e4a64f" radius={[5,5,0,0]} maxBarSize={35}/></BarChart></ResponsiveContainer></Box></Panel></Grid></Grid><Panel title="Request performance detail" subtitle="Use the export option to work with the current dataset"><RequestTable rows={requests} onOpen={r=>window.location.assign(`/requests/${r.id}`)}/></Panel></>}
function UsersPage(){const {users,setUsers,setAudit,user}=useApp();const [query,setQuery]=useState('');const [open,setOpen]=useState(false);const [form,setForm]=useState({name:'',email:'',role:'Staff'});const [editing,setEditing]=useState(null);const filtered=users.filter(u=>`${u.name} ${u.email} ${u.role}`.toLowerCase().includes(query.toLowerCase()));function save(){if(!form.name.trim()||!form.email.includes('@'))return;const id=editing||String(Date.now());setUsers(old=>editing?old.map(u=>u.id===editing?{...u,...form}:u):[...old,{id,...form,active:true}]);setAudit(old=>[{id:Date.now(),actor:user.name,action:editing?'USER_UPDATED':'USER_CREATED',entity:form.email,time:new Date().toLocaleString(),details:`${editing?'Updated':'Created'} user account`},...old]);setOpen(false);setEditing(null);setForm({name:'',email:'',role:'Staff'})}return <><PageTitle title="User management" subtitle="Manage municipal accounts, roles and account access." action={<Button variant="contained" startIcon={<AddOutlinedIcon/>} onClick={()=>{setEditing(null);setForm({name:'',email:'',role:'Staff'});setOpen(true)}}>Add user</Button>}/><Paper className="filter-panel" elevation={0}><TextField size="small" placeholder="Search name, email or role" value={query} onChange={e=>setQuery(e.target.value)} InputProps={{startAdornment:<SearchOutlinedIcon sx={{mr:1,color:'#829198'}}/>}} className="search-field"/><Chip label={`${users.length} accounts`} variant="outlined"/></Paper><Panel title="Municipal accounts" subtitle="Only administrators can change roles or deactivate accounts."><Table><TableHead><TableRow>{['User','Role','Status','Account actions'].map(v=><TableCell key={v}>{v}</TableCell>)}</TableRow></TableHead><TableBody>{filtered.map(u=><TableRow key={u.id}><TableCell><Box className="user-cell"><Avatar sx={{bgcolor:'#e1efed',color:'#176b67',fontWeight:800}}>{u.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</Avatar><Box><Typography className="table-primary">{u.name}</Typography><Typography className="table-secondary">{u.email}</Typography></Box></Box></TableCell><TableCell><FormControl size="small" sx={{minWidth:150}}><Select value={u.role} onChange={e=>{setUsers(old=>old.map(x=>x.id===u.id?{...x,role:e.target.value}:x));setAudit(old=>[{id:Date.now(),actor:user.name,action:'ROLE_UPDATED',entity:u.email,time:new Date().toLocaleString(),details:`Role changed to ${e.target.value}`},...old])}}>{['Requester','Staff','Manager','Administrator'].map(r=><MenuItem key={r} value={r}>{r}</MenuItem>)}</Select></FormControl></TableCell><TableCell><StatusChip status={u.active?'Active':'Inactive'}/></TableCell><TableCell><Stack direction="row" spacing={1}><Button size="small" startIcon={<EditOutlinedIcon/>} onClick={()=>{setEditing(u.id);setForm({name:u.name,email:u.email,role:u.role});setOpen(true)}}>Edit</Button><Button size="small" color={u.active?'error':'success'} onClick={()=>setUsers(old=>old.map(x=>x.id===u.id?{...x,active:!x.active}:x))}>{u.active?'Deactivate':'Activate'}</Button></Stack></TableCell></TableRow>)}</TableBody></Table></Panel><Dialog open={open} onClose={()=>setOpen(false)} fullWidth maxWidth="sm"><DialogTitle>{editing?'Edit user':'Create user account'}</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><TextField label="Full name" required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><TextField label="Email address" type="email" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/><FormControl><InputLabel>Role</InputLabel><Select label="Role" value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>{['Requester','Staff','Manager','Administrator'].map(r=><MenuItem key={r} value={r}>{r}</MenuItem>)}</Select></FormControl></Stack></DialogContent><DialogActions><Button onClick={()=>setOpen(false)}>Cancel</Button><Button variant="contained" onClick={save}>Save account</Button></DialogActions></Dialog></>}
function CategoriesPage(){const {categoryList,setCategoryList,setAudit,user}=useApp();const [open,setOpen]=useState(false);const [editing,setEditing]=useState(null);const [form,setForm]=useState({name:'',description:''});function save(){if(!form.name.trim())return;setCategoryList(old=>editing?old.map(c=>c.id===editing?{...c,...form}:c):[...old,{...form,id:String(Date.now()),isActive:true,color:'#e0f1ef'}]);setAudit(old=>[{id:Date.now(),actor:user.name,action:editing?'CATEGORY_UPDATED':'CATEGORY_CREATED',entity:form.name,time:new Date().toLocaleString(),details:'Category configuration changed'},...old]);setOpen(false);setEditing(null);setForm({name:'',description:''})}return <><PageTitle title="Category management" subtitle="Keep request categories clear, relevant and easy for residents to choose." action={<Button variant="contained" startIcon={<AddOutlinedIcon/>} onClick={()=>{setEditing(null);setForm({name:'',description:''});setOpen(true)}}>Add category</Button>}/><Grid container spacing={2}>{categoryList.map(c=><Grid item xs={12} sm={6} lg={4} key={c.id||c._id}><Paper elevation={0} className="category-card"><Box className="category-icon-box" sx={{bgcolor:c.color||'#e0f1ef'}}><CategoryOutlinedIcon/></Box><Box className="category-card-title"><Typography className="panel-title">{c.name}</Typography><StatusChip status={c.isActive===false?'Inactive':'Active'}/></Box><Typography className="category-description">{c.description||'No description provided.'}</Typography><Divider sx={{my:2}}/><Stack direction="row" justifyContent="space-between"><Button size="small" startIcon={<EditOutlinedIcon/>} onClick={()=>{setEditing(c.id||c._id);setForm({name:c.name,description:c.description||''});setOpen(true)}}>Edit details</Button><Button size="small" color={c.isActive===false?'success':'error'} startIcon={<DeleteOutlineOutlinedIcon/>} onClick={()=>setCategoryList(old=>old.map(x=>(x.id||x._id)===(c.id||c._id)?{...x,isActive:x.isActive===false}:x))}>{c.isActive===false?'Activate':'Deactivate'}</Button></Stack></Paper></Grid>)}</Grid><Dialog open={open} onClose={()=>setOpen(false)} fullWidth maxWidth="sm"><DialogTitle>{editing?'Edit category':'Add request category'}</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><TextField label="Category name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><TextField label="Description" multiline minRows={3} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Stack></DialogContent><DialogActions><Button onClick={()=>setOpen(false)}>Cancel</Button><Button variant="contained" onClick={save}>Save category</Button></DialogActions></Dialog></>}
function AuditLogsPage(){const {audit}=useApp();const [query,setQuery]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const filtered=audit.filter(a=>{const match=`${a.actor} ${a.action} ${a.entity} ${a.details}`.toLowerCase().includes(query.toLowerCase());const date=new Date(a.time);const start=from?new Date(`${from}T00:00:00`):null;const end=to?new Date(`${to}T23:59:59`):null;return match&&(!start||date>=start)&&(!end||date<=end)});return <><PageTitle title="Audit trail" subtitle="Search and filter key actions recorded across the platform." action={<Stack direction="row" spacing={1}><Button variant="outlined" startIcon={<FileDownloadOutlinedIcon/>} onClick={()=>downloadCSV(filtered.map(a=>({actor:a.actor,action:a.action,entity:a.entity,time:a.time,details:a.details})))}>Export CSV</Button><Button variant="contained" onClick={()=>window.print()}>Print / Save PDF</Button></Stack>}/><Alert severity="info" sx={{mb:2.5,borderRadius:2}}>This is demo-session audit data. Production logs must be stored server-side, append-only, access-scoped, and export events must themselves be audited.</Alert><Paper className="filter-panel" elevation={0}><TextField size="small" placeholder="Search actor, action or record" value={query} onChange={e=>setQuery(e.target.value)} className="search-field" InputProps={{startAdornment:<SearchOutlinedIcon sx={{mr:1,color:'#829198'}}/>}}/><TextField size="small" type="date" label="From" InputLabelProps={{shrink:true}} value={from} onChange={e=>setFrom(e.target.value)}/><TextField size="small" type="date" label="To" InputLabelProps={{shrink:true}} value={to} onChange={e=>setTo(e.target.value)}/><Chip label={`${filtered.length} events`} variant="outlined"/></Paper><Panel title="Recorded system events" subtitle="Most recent events appear first."><Table><TableHead><TableRow>{['Actor','Action','Related record','Timestamp','Details'].map(v=><TableCell key={v}>{v}</TableCell>)}</TableRow></TableHead><TableBody>{filtered.map(a=><TableRow key={a.id}><TableCell><Typography className="table-primary">{a.actor}</Typography></TableCell><TableCell><Chip label={a.action} size="small" variant="outlined" sx={{fontWeight:700,fontSize:10.5}}/></TableCell><TableCell><Typography className="table-secondary">{a.entity}</Typography></TableCell><TableCell><Typography className="table-secondary">{a.time}</Typography></TableCell><TableCell><Typography className="table-secondary">{a.details}</Typography></TableCell></TableRow>)}{!filtered.length&&<TableRow><TableCell colSpan={5}>No events match the selected filters.</TableCell></TableRow>}</TableBody></Table></Panel></>}
function AlertsPage(){const {emergency,setEmergency,setAudit,user}=useApp();const [draft,setDraft]=useState(emergency);const [saved,setSaved]=useState(false);function simulate(enabled){const next={...emergency,isActive:enabled,simulated:enabled,detectedAt:enabled?new Date().toISOString():emergency.detectedAt,title:emergency.title||'Simulated database outage',message:emergency.message||'This is a simulated outage for testing the notification workflow.',severity:'High',estimatedRecovery:'Unknown'};setEmergency(next);setDraft(next);setAudit(old=>[{id:Date.now(),actor:user.name,action:enabled?'DOWNTIME_SIMULATION_ENABLED':'DOWNTIME_SIMULATION_DISABLED',entity:'Database downtime simulation',time:new Date().toLocaleString(),details:enabled?'Simulation enabled in frontend demo':'Simulation disabled in frontend demo'},...old]);}function save(){if(draft.fallbackFormUrl && !/^https:\/\//i.test(draft.fallbackFormUrl.trim())){setSaved(false);window.alert('Fallback link must begin with https://');return}setEmergency({...draft,fallbackFormUrl:draft.fallbackFormUrl.trim()});setAudit(old=>[{id:Date.now(),actor:user.name,action:'EMERGENCY_ALERT_UPDATED',entity:'Public emergency banner',time:new Date().toLocaleString(),details:draft.isActive?'Emergency banner enabled':'Emergency banner disabled'},...old]);setSaved(true)}return <><PageTitle title="Downtime and fallback" subtitle="Configure the Google Form fallback and test the downtime warning workflow."/><Alert severity="warning" sx={{mb:2}}>Simulation affects only this frontend demo session. Production outage detection must come from backend health checks; never disconnect or disrupt the production database to test this UI.</Alert><Stack direction="row" spacing={1} sx={{mb:2}}><Button variant="contained" color="warning" disabled={!!emergency.simulated} onClick={()=>simulate(true)}>Simulate database outage</Button><Button variant="outlined" disabled={!emergency.simulated} onClick={()=>simulate(false)}>End simulation</Button><Chip label={emergency.simulated?'Simulation active':emergency.isActive?'Outage notice active':'No outage notice'} color={emergency.isActive?'warning':'default'}/></Stack><Grid container spacing={2.5}><Grid item xs={12} lg={7}><Paper elevation={0} className="form-panel"><Box className="settings-row"><Box><Typography className="panel-title">Public emergency banner</Typography><Typography className="panel-subtitle">Display an important service interruption notice to visitors.</Typography></Box><Switch checked={draft.isActive} onChange={e=>setDraft({...draft,isActive:e.target.checked})} color="primary"/></Box><Divider sx={{my:2.5}}/><Stack spacing={2.5}><TextField label="Alert heading" fullWidth value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/><TextField label="Public message" fullWidth multiline minRows={4} value={draft.message} onChange={e=>setDraft({...draft,message:e.target.value})}/><TextField label="Alternative form URL" fullWidth value={draft.fallbackFormUrl} onChange={e=>setDraft({...draft,fallbackFormUrl:e.target.value})} helperText="Provide a verified alternative reporting URL before enabling in production."/><Box sx={{display:'flex',justifyContent:'flex-end'}}><Button variant="contained" onClick={save}>Save alert settings</Button></Box>{saved&&<Alert severity="success" onClose={()=>setSaved(false)}>Alert settings saved for this demo session.</Alert>}</Stack></Paper></Grid><Grid item xs={12} lg={5}><Panel title="Public preview" subtitle="This is how the notice will appear in the platform."><Box className={`alert-preview ${draft.isActive?'':'alert-preview-muted'}`}><WarningAmberOutlinedIcon/><Box><Typography className="alert-preview-title">{draft.title||'Alert heading'}</Typography><Typography className="alert-preview-copy">{draft.message||'Your public message will appear here.'}</Typography>{draft.isActive&&<Button size="small" variant="outlined" href={draft.fallbackFormUrl} target="_blank" rel="noreferrer">Alternative reporting channel</Button>}</Box></Box><Typography className="table-secondary" sx={{mt:2}}>The production service should activate this fallback automatically when the API health check fails.</Typography></Panel></Grid></Grid></>}
function SettingsPage(){
 const {user,setUser}=useApp();
 const [name,setName]=useState(user?.name||'');
 const [email,setEmail]=useState(user?.email||'');
 const [busy,setBusy]=useState(false);
 const [message,setMessage]=useState(null);
 const [preferences,setPreferences]=useState(()=>{try{return JSON.parse(localStorage.getItem('civicconnect.preferences')||'{}')}catch{return {}}});
 useEffect(()=>{setName(user?.name||'');setEmail(user?.email||'')},[user?.name,user?.email]);
 function toggle(key,checked){const next={...preferences,[key]:checked};setPreferences(next);localStorage.setItem('civicconnect.preferences',JSON.stringify(next))}
 async function save(){setBusy(true);setMessage(null);try{const result=await apiRequest('/auth/profile',{method:'PATCH',body:JSON.stringify({name,email})});setUser(result.user);setMessage({severity:'success',text:'Profile saved to MongoDB.'})}catch(e){setMessage({severity:'error',text:e.message})}finally{setBusy(false)}}
 return <><PageTitle title="Settings" subtitle="Manage your profile and local interface preferences."/><Grid container spacing={2.5}><Grid item xs={12} md={7}><Paper elevation={0} className="form-panel"><Typography className="panel-title">Profile information</Typography><Typography className="panel-subtitle" sx={{mb:3}}>Profile changes are saved through the authenticated backend.</Typography><Stack spacing={2.5}><TextField label="Full name" value={name} onChange={e=>setName(e.target.value)} fullWidth/><TextField label="Email address" value={email} onChange={e=>setEmail(e.target.value)} fullWidth/><TextField label="Workspace role" value={user?.role||'Requester'} fullWidth disabled/><Box sx={{display:'flex',justifyContent:'flex-end'}}><Button variant="contained" disabled={busy||name.trim().length<2||!email.includes('@')} onClick={save}>{busy?'Saving…':'Save changes'}</Button></Box>{message&&<Alert severity={message.severity} onClose={()=>setMessage(null)}>{message.text}</Alert>}</Stack></Paper></Grid><Grid item xs={12} md={5}><Panel title="Workspace preferences" subtitle="Stored locally in this browser; notification delivery is not implemented"><Box className="preference-row"><Box><Typography className="table-primary">Email notification preference</Typography><Typography className="table-secondary">Preference only; email delivery is not connected.</Typography></Box><Switch checked={Boolean(preferences.emailNotifications)} onChange={e=>toggle('emailNotifications',e.target.checked)}/></Box><Divider/><Box className="preference-row"><Box><Typography className="table-primary">Weekly summary preference</Typography><Typography className="table-secondary">Preference only; scheduled summaries are not implemented.</Typography></Box><Switch checked={Boolean(preferences.weeklySummary)} onChange={e=>toggle('weeklySummary',e.target.checked)}/></Box><Divider/><Box className="preference-row"><Box><Typography className="table-primary">Compact tables preference</Typography><Typography className="table-secondary">Saved locally; table layout integration pending.</Typography></Box><Switch checked={Boolean(preferences.compactTables)} onChange={e=>toggle('compactTables',e.target.checked)}/></Box></Panel><Panel title="About CivicConnect"><Typography className="body-copy">CivicConnect supports accountable municipal service delivery.</Typography><Typography className="table-secondary" sx={{mt:2}}>Prototype — not release verified</Typography></Panel></Grid></Grid></>
}
function HelpPage(){return <><PageTitle title="Help centre" subtitle="Guidance for using CivicConnect municipal services."/><Grid container spacing={2}><Grid item xs={12} md={4}><Panel title="Submitting a request"><Typography className="body-copy">Choose a service category, explain the issue, and provide a clear physical location. Save your tracking number so you can find your request later.</Typography></Panel></Grid><Grid item xs={12} md={4}><Panel title="Tracking progress"><Typography className="body-copy">Open Service requests and select a record to see its current status, assigned team and available updates.</Typography></Panel></Grid><Grid item xs={12} md={4}><Panel title="Urgent safety concerns"><Typography className="body-copy">Do not rely on this portal for immediate emergencies. Contact the appropriate emergency service for urgent threats to life or safety.</Typography></Panel></Grid></Grid></>}
function DataSourcePage(){
 const {dataSource,setDataSource,user}=useApp();const [saved,setSaved]=useState(false);const [error,setError]=useState('');const [busy,setBusy]=useState(false);
 async function save(v){setSaved(false);setError('');setBusy(true);try{if(user?.role!=='Administrator')throw new Error('Only Administrators can change the data-source setting.');await apiRequest('/settings/dataSourceMode',{method:'PUT',body:JSON.stringify({value:v})});setDataSource(v);setSaved(true)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <><PageTitle title="Data source management" subtitle="Administrator-controlled mode for prototype data display."/><Alert severity="warning" sx={{mb:2}}>This selection is persisted in system settings, but the backend does not yet enforce the selected mode across every API, report and export. Demo records must not be treated as live records.</Alert><Grid container spacing={2}>{[{v:'dummy',title:'Dummy data only',desc:'Use sample requests for demonstration.'},{v:'mongodb',title:'MongoDB data only',desc:'Load records from the authenticated backend.'},{v:'both',title:'Dummy and MongoDB',desc:'Display both sources, with demo records visibly distinguished.'}].map(o=><Grid item xs={12} md={4} key={o.v}><Paper elevation={0} className="form-panel" sx={{height:'100%',border:dataSource===o.v?'2px solid #176b67':'1px solid #e4e9e9'}}><Typography className="panel-title">{o.title}</Typography><Typography className="body-copy" sx={{my:2}}>{o.desc}</Typography><Chip label={dataSource===o.v?'Currently selected':'Available mode'} color={dataSource===o.v?'success':'default'} variant="outlined"/><Button sx={{mt:2}} fullWidth disabled={busy||user?.role!=='Administrator'} variant={dataSource===o.v?'outlined':'contained'} onClick={()=>save(o.v)}>{dataSource===o.v?'Selected':'Select mode'}</Button></Paper></Grid>)}</Grid>{saved&&<Alert sx={{mt:2}} severity="success" onClose={()=>setSaved(false)}>Setting saved in MongoDB. Backend-wide enforcement remains outstanding.</Alert>}{error&&<Alert sx={{mt:2}} severity="error">{error}</Alert>}<Panel title="Remaining integration work" subtitle="Not yet verified"><ul><li>Apply the mode in all backend query services, reports and exports.</li><li>Maintain distinct demo/live source labels.</li><li>Retain server-side role and ownership restrictions.</li><li>Verify setting persistence and audit logs through integration tests.</li></ul></Panel></>
}
function ImportPage(){const {imports,setImports,setAudit,user}=useApp();const [source,setSource]=useState('excel');const [sheetUrl,setSheetUrl]=useState('');const [fileName,setFileName]=useState('');const [rows,setRows]=useState([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function readFile(file){setError('');setFileName(file.name);try{const buf=await file.arrayBuffer();const wb=XLSX.read(buf,{type:'array',cellDates:true});const ws=wb.Sheets[wb.SheetNames[0]];const parsed=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});setRows(parsed);if(!parsed.length)setError('No data rows were found in the first worksheet.')}catch(e){setRows([]);setError('The file could not be read. Upload a valid .xlsx, .xls, or .csv file.')}}function previewSheet(){setError('');if(!/^https:\/\/(docs\.google\.com\/spreadsheets\/d\/|docs\.google\.com\/spreadsheets\/u\/\d+\/d\/)/i.test(sheetUrl.trim())){setError('Enter a Google Sheets URL using the supported docs.google.com/spreadsheets format.');return}setError('This frontend validates the URL format only. A backend integration is required to fetch and preview Google Sheets rows.')}function runImport(){if(!rows.length){setError('Choose a file with data rows before starting a preview import.');return}setBusy(true);const keys=Object.keys(rows[0]||{});const seen=new Set();let duplicate=0,invalid=0;const valid=[];rows.forEach((r,i)=>{const normalized=JSON.stringify(Object.entries(r).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,String(v).trim().toLowerCase()]));if(seen.has(normalized)){duplicate++;return}seen.add(normalized);const title=String(r.title||r.Title||r.subject||r.Subject||'').trim();const description=String(r.description||r.Description||r.details||r.Details||'').trim();if(!title||!description){invalid++;return}valid.push(r)});const job={id:'IMP-'+Date.now(),source:source==='excel'?fileName:sheetUrl,createdBy:user.name,startedAt:new Date().toISOString(),total:rows.length,newCandidates:valid.length,duplicatesInFile:duplicate,invalid,headers:keys,status:'Preview only'};setImports(old=>[job,...old]);setAudit(old=>[{id:Date.now(),actor:user.name,action:'IMPORT_PREVIEW_CREATED',entity:job.id,time:new Date().toLocaleString(),details:`${job.total} rows reviewed; ${job.newCandidates} candidates, ${job.duplicatesInFile} in-file duplicates, ${job.invalid} invalid`},...old]);setBusy(false);setError('Preview completed. This prototype does not write records to MongoDB or compare against the live database.');}return <><PageTitle title="Data imports" subtitle="Preview Excel files and configure public Google Sheets imports before a backend import service is connected."/><Alert severity="warning" sx={{mb:2}}>Import execution is intentionally preview-only. No request is inserted into MongoDB from this frontend.</Alert><Paper className="form-panel" elevation={0}><Stack spacing={2.5}><FormControl><InputLabel>Import source</InputLabel><Select value={source} label="Import source" onChange={e=>{setSource(e.target.value);setRows([]);setError('')}}><MenuItem value="excel">Upload Excel or CSV file</MenuItem><MenuItem value="sheets">Public Google Sheets URL</MenuItem></Select></FormControl>{source==='excel'?<Button component="label" variant="outlined" startIcon={<FileDownloadOutlinedIcon/>}>Choose .xlsx, .xls, or .csv file<input hidden type="file" accept=".xlsx,.xls,.csv" onChange={e=>e.target.files?.[0]&&readFile(e.target.files[0])}/></Button>:<><TextField label="Public Google Sheets URL" fullWidth value={sheetUrl} onChange={e=>setSheetUrl(e.target.value)} placeholder="https://docs.google.com/spreadsheets/d/..."/><Button variant="outlined" onClick={previewSheet}>Validate sheet URL</Button></>}{fileName&&<Typography variant="body2">Selected file: {fileName}</Typography>}{rows.length>0&&<Alert severity="info">Loaded {rows.length} rows for local preview. Columns: {Object.keys(rows[0]).join(', ')}</Alert>}{error&&<Alert severity={error.startsWith('Preview completed')?'info':'error'}>{error}</Alert>}<Box><Button variant="contained" disabled={!rows.length||busy} onClick={runImport}>Validate and preview import</Button></Box></Stack></Paper><Panel title="Import history" subtitle="Preview jobs recorded during this session"><Table size="small"><TableHead><TableRow>{['Job','Source','Started','Rows','Candidates','Duplicates','Invalid','Status'].map(h=><TableCell key={h}>{h}</TableCell>)}</TableRow></TableHead><TableBody>{imports.map(j=><TableRow key={j.id}><TableCell>{j.id}</TableCell><TableCell>{j.source}</TableCell><TableCell>{new Date(j.startedAt).toLocaleString()}</TableCell><TableCell>{j.total}</TableCell><TableCell>{j.newCandidates}</TableCell><TableCell>{j.duplicatesInFile}</TableCell><TableCell>{j.invalid}</TableCell><TableCell><Chip size="small" label={j.status}/></TableCell></TableRow>)}{!imports.length&&<TableRow><TableCell colSpan={8}>No import jobs in this session.</TableCell></TableRow>}</TableBody></Table></Panel><Panel title="Import rules required in production"><ul><li>Map and validate required columns before import.</li><li>Compare stable source IDs and normalized fingerprints against MongoDB.</li><li>Separate exact duplicates from potential duplicates requiring review.</li><li>Use unique indexes and idempotent writes to handle concurrent or repeated imports.</li><li>Preserve source submission timestamps and record importedAt, source, sourceRecordId and importJobId.</li></ul></Panel></>}
function NotificationsPage(){const {notifications,setNotifications,setAudit,user}=useApp();const blank={title:'',message:'',category:'Maintenance',priority:'Medium',startAt:new Date().toISOString().slice(0,16),expiresAt:'',status:'Draft',audience:'Everyone'};const [draft,setDraft]=useState(blank);const [editing,setEditing]=useState(null);const [saved,setSaved]=useState(false);function save(){if(!draft.title.trim()||!draft.message.trim()||!draft.expiresAt){return}const id=editing||`N-${Date.now()}`;const item={...draft,id,status:draft.status==='Published'?'Published':'Draft',updatedAt:new Date().toISOString(),updatedBy:user.name};setNotifications(old=>editing?old.map(n=>n.id===editing?item:n):[item,...old]);setAudit(old=>[{id:Date.now(),actor:user.name,action:editing?'NOTIFICATION_UPDATED':'NOTIFICATION_CREATED',entity:id,time:new Date().toLocaleString(),details:`${item.status}: ${item.title}`},...old]);setDraft(blank);setEditing(null);setSaved(true)}function edit(n){setDraft({...n});setEditing(n.id)}function publish(n){const updated={...n,status:'Published',publishedAt:new Date().toISOString()};setNotifications(old=>old.map(x=>x.id===n.id?updated:x));setAudit(old=>[{id:Date.now(),actor:user.name,action:'NOTIFICATION_PUBLISHED',entity:n.id,time:new Date().toLocaleString(),details:n.title},...old])}return <><PageTitle title="Notification management" subtitle="Draft, schedule and publish community service announcements."/><Grid container spacing={2.5}><Grid item xs={12} md={5}><Paper className="form-panel" elevation={0}><Typography className="panel-title">{editing?'Edit notification':'Create notification'}</Typography><Stack spacing={2} sx={{mt:2}}><TextField label="Title" required value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/><TextField label="Message" required multiline minRows={3} value={draft.message} onChange={e=>setDraft({...draft,message:e.target.value})}/><FormControl><InputLabel>Category</InputLabel><Select label="Category" value={draft.category} onChange={e=>setDraft({...draft,category:e.target.value})}>{['Power outage','Maintenance','Service interruption','Security notice','Recovery update','Planned downtime','General'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><FormControl><InputLabel>Priority</InputLabel><Select label="Priority" value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value})}>{['Low','Medium','High','Critical'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><FormControl><InputLabel>Audience</InputLabel><Select label="Audience" value={draft.audience} onChange={e=>setDraft({...draft,audience:e.target.value})}>{['Everyone','Requesters','Managers','Administrators'].map(v=><MenuItem key={v} value={v}>{v}</MenuItem>)}</Select></FormControl><TextField label="Start date and time" type="datetime-local" InputLabelProps={{shrink:true}} value={draft.startAt} onChange={e=>setDraft({...draft,startAt:e.target.value})}/><TextField label="Expiry date and time" required type="datetime-local" InputLabelProps={{shrink:true}} value={draft.expiresAt} onChange={e=>setDraft({...draft,expiresAt:e.target.value})}/><Stack direction="row" spacing={1}><Button variant="contained" onClick={save}>Save draft</Button><Button variant="outlined" onClick={()=>{setDraft(blank);setEditing(null)}}>Clear</Button></Stack>{saved&&<Alert severity="success" onClose={()=>setSaved(false)}>Notification saved in this demo session.</Alert>}</Stack></Paper></Grid><Grid item xs={12} md={7}><Panel title="Notification register" subtitle="Expired records remain in this register for audit purposes"><Table size="small"><TableHead><TableRow>{['Title','Priority','Audience','Expiry','Status','Actions'].map(h=><TableCell key={h}>{h}</TableCell>)}</TableRow></TableHead><TableBody>{notifications.map(n=>{const expired=n.expiresAt&&new Date(n.expiresAt)<new Date();return <TableRow key={n.id}><TableCell>{n.title}</TableCell><TableCell><Chip size="small" label={n.priority}/></TableCell><TableCell>{n.audience}</TableCell><TableCell>{n.expiresAt?new Date(n.expiresAt).toLocaleString():'Not set'}</TableCell><TableCell><Chip size="small" label={expired?'Expired':n.status}/></TableCell><TableCell><Stack direction="row"><Button size="small" onClick={()=>edit(n)}>Edit</Button><Button size="small" disabled={n.status==='Published'||expired} onClick={()=>publish(n)}>Publish</Button></Stack></TableCell></TableRow>})}</TableBody></Table></Panel></Grid></Grid><Alert sx={{mt:2}} severity="info">The prototype evaluates expiry when rendering the list. Production must enforce schedule and expiry on the server and retain archived records for audit.</Alert></>}
function LoginPage(){const {setUser}=useApp();const nav=useNavigate();const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function signIn(e){e.preventDefault();setError('');setBusy(true);try{const account=await apiLogin(email.trim(),password);setUser(account);nav('/')}catch(err){setError(err.message||'Unable to sign in. Check your details and try again.')}finally{setBusy(false)}}return <Box className="auth-screen"><Paper elevation={0} className="auth-card"><Box className="brand auth-brand"><Box className="brand-mark"><FactCheckOutlinedIcon/></Box><Box><Typography className="brand-name">CivicConnect</Typography><Typography className="brand-sub">MUNICIPAL SERVICES</Typography></Box></Box><Typography className="auth-title">Welcome back</Typography><Typography className="auth-subtitle">Sign in to access your municipal service workspace.</Typography><Box component="form" onSubmit={signIn} sx={{mt:3}}><Stack spacing={2}><TextField label="Email address" type="email" required value={email} onChange={e=>setEmail(e.target.value)} fullWidth autoComplete="email"/><TextField label="Password" type="password" required value={password} onChange={e=>setPassword(e.target.value)} fullWidth autoComplete="current-password"/>{error&&<Alert severity="error">{error}</Alert>}<Button type="submit" variant="contained" fullWidth size="large" disabled={busy}>{busy?'Signing in…':'Sign in'}</Button></Stack></Box><Typography className="auth-note">Your credentials are verified by the CivicConnect API. Access is determined by your database account and assigned role.</Typography><Button fullWidth onClick={()=>nav('/register')}>Create a citizen account</Button></Paper></Box>}
function RegisterPage(){const {setUser}=useApp();const nav=useNavigate();const [f,setF]=useState({name:'',email:'',password:''});const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setError('');if(f.name.trim().length<2||!f.email.includes('@')||f.password.length<10){setError('Enter your full name, a valid email, and a password of at least 10 characters.');return}setBusy(true);try{await registerAccount(f.name.trim(),f.email.trim(),f.password);setUser(null);nav('/login',{state:{registered:true}})}catch(err){setError(err.message||'Unable to create account.')}finally{setBusy(false)}}return <Box className="auth-screen"><Paper elevation={0} className="auth-card"><Box className="brand auth-brand"><Box className="brand-mark"><FactCheckOutlinedIcon/></Box><Box><Typography className="brand-name">CivicConnect</Typography><Typography className="brand-sub">MUNICIPAL SERVICES</Typography></Box></Box><Typography className="auth-title">Create your account</Typography><Typography className="auth-subtitle">Register to submit and track municipal service requests.</Typography><Box component="form" onSubmit={submit} sx={{mt:3}}><Stack spacing={2}><TextField label="Full name" required value={f.name} onChange={e=>setF({...f,name:e.target.value})} autoComplete="name"/><TextField label="Email address" type="email" required value={f.email} onChange={e=>setF({...f,email:e.target.value})} autoComplete="email"/><TextField label="Password" type="password" required value={f.password} onChange={e=>setF({...f,password:e.target.value})} helperText="Use at least 10 characters." autoComplete="new-password"/>{error&&<Alert severity="error">{error}</Alert>}<Button type="submit" variant="contained" fullWidth size="large" disabled={busy}>{busy?'Creating account…':'Create account'}</Button></Stack></Box><Typography className="auth-note">Public registration creates a Requester account only. Staff, Manager and Administrator roles must be assigned by an authorised administrator.</Typography><Button fullWidth onClick={()=>nav('/login')}>Already registered? Sign in</Button></Paper></Box>}
function NotFound(){return <Box className="not-found"><Typography className="not-found-code">404</Typography><Typography className="section-title">Page not found</Typography><Typography className="section-subtitle">The page you are looking for does not exist.</Typography><Button variant="contained" sx={{mt:2}} onClick={()=>window.location.assign('/')}>Return to overview</Button></Box>}
export default function App(){const {user,authLoading}=useApp();if(authLoading)return <Box className="auth-screen"><Typography>Restoring your secure session…</Typography></Box>;return <Routes><Route path="/login" element={<LoginPage/>}/><Route path="/register" element={<RegisterPage/>}/><Route element={user?<AppLayout/>:<Navigate to="/login" replace/>}><Route path="/" element={<Dashboard/>}/><Route path="/requests" element={<RequestsPage/>}/><Route path="/requests/:id" element={<RequestDetail/>}/><Route path="/new-request" element={user?.role==='Requester'?<NewRequestPage/>:<Navigate to="/" replace/>}/><Route path="/reports" element={['Manager','Administrator'].includes(user?.role)?<ReportsPage/>:<Navigate to="/" replace/>}/><Route path="/users" element={user?.role==='Administrator'?<UsersDatabasePage/>:<Navigate to="/" replace/>}/><Route path="/categories" element={user?.role==='Administrator'?<CategoriesDatabasePage/>:<Navigate to="/" replace/>}/><Route path="/audit-logs" element={user?.role==='Administrator'?<AuditTrailPage/>:<Navigate to="/" replace/>}/><Route path="/system-alerts" element={user?.role==='Administrator'?<SystemAlertsDatabasePage/>:<Navigate to="/" replace/>}/><Route path="/data-source" element={user?.role==='Administrator'?<DataSourcePage/>:<Navigate to="/" replace/>}/><Route path="/imports" element={user?.role==='Administrator'?<ImportPage/>:<Navigate to="/" replace/>}/><Route path="/notifications" element={user?.role==='Administrator'?<NotificationsPage/>:<Navigate to="/" replace/>}/><Route path="/settings" element={<SettingsPage/>}/><Route path="/help" element={<HelpPage/>}/><Route path="*" element={<NotFound/>}/></Route></Routes>}
